// packages/data/repositories/_baseRepo.js
export class BaseRepository {
    /**
     * @param {import('better-sqlite3').Database} db
     * @param {string} tableName
     * @param {object} options
     */
    constructor(db, tableName, { defaultOrderBy = 'rowid', filterableColumns = [] } = {}) {
        this.db = db;
        this.table = tableName;
        this.defaultOrderBy = defaultOrderBy;
        this.filterableColumns = filterableColumns;
    }

    // ── Leitura ────────────────────────────────────────────────────────
    findAll({ filters = {}, page = 1, pageSize = 5 } = {}) {
        const { where, params } = this.#buildWhere(filters);

        const total = this.db
            .prepare(`SELECT COUNT(*) AS total FROM ${this.table} ${where}`)
            .get(params).total;

        const totalPages = Math.max(1, Math.ceil(total / pageSize));
        const currentPage = Math.min(Math.max(page, 1), totalPages);
        const offset = (currentPage - 1) * pageSize;

        const rows = this.db.prepare(`
            SELECT * FROM ${this.table}
            ${where}
            ORDER BY ${this.defaultOrderBy}
            LIMIT @limit OFFSET @offset
        `).all({ ...params, limit: pageSize, offset });

        return {
            data: rows,
            pagination: { page: currentPage, pageSize, totalRecords: total, totalPages }
        };
    }

    findById(id) {
        return this.db
            .prepare(`SELECT * FROM ${this.table} WHERE id = ?`)
            .get(id) ?? null;
    }

    // ── Escrita ────────────────────────────────────────────────────────
    insert(row) {
        const cols = Object.keys(row);
        const sql = `INSERT INTO ${this.table} (${cols.join(', ')})
                      VALUES (${cols.map(c => `@${c}`).join(', ')})`;
        this.db.prepare(sql).run(row);
        return row;
    }

    update(row) {
        const { id, ...fields } = row;
        const sets = Object.keys(fields).map(c => `${c} = @${c}`).join(', ');
        const info = this.db.prepare(
            `UPDATE ${this.table} SET ${sets} WHERE id = @id`
        ).run(row);
        if (info.changes === 0)
            throw new Error(`[${this.table}] Registro não encontrado: ${id}`);
        return this.findById(id);
    }

    softDelete(id, autorUUID, dataUTC) {
        const info = this.db.prepare(`
            UPDATE ${this.table}
            SET excluidoEm  = @excluidoEm,
                excluidoPor = @excluidoPor
            WHERE id = @id AND excluidoEm IS NULL
        `).run({ id, excluidoEm: dataUTC, excluidoPor: autorUUID });
        if (info.changes === 0)
            throw new Error(`[${this.table}] Não encontrado ou já excluído: ${id}`);
    }

    hardDelete(id) {
        const info = this.db
            .prepare(`DELETE FROM ${this.table} WHERE id = ?`)
            .run(id);
        if (info.changes === 0)
            throw new Error(`[${this.table}] Registro não encontrado: ${id}`);
    }

    transaction(fn) { return this.db.transaction(fn)(); }

    // ── Privado ────────────────────────────────────────────────────────
    #buildWhere(filters = {}) {
        const conditions = ['excluidoEm IS NULL'];
        const params = {};
        for (const [col, val] of Object.entries(filters)) {
            if (!val || !this.filterableColumns.includes(col)) continue;
            conditions.push(`${col} = @${col}`);
            params[col] = val;
        }
        return {
            where: `WHERE ${conditions.join(' AND ')}`,
            params
        };
    }
}